import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.BY72S51x.js";const r="/aibutler/docs-versions/v1.1.9/img/en/settings-datadir.png",u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md"}'),s={name:"en/guide/faq.md"};function i(h,e,d,l,g,c){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Whenever something goes wrong, the first step is always to <strong>tell your persona what&#39;s happening</strong>: the exact error, what you did, and what you expected. It can see a lot that you can&#39;t, and it can usually figure out most problems on its own.</p><h2 id="installing-and-launching" tabindex="-1">Installing and launching <a class="header-anchor" href="#installing-and-launching" aria-label="Permalink to &quot;Installing and launching&quot;">​</a></h2><p><strong>Mac asks whether you&#39;re sure you want to open it</strong> macOS asks this for every app downloaded from the internet. Click <strong>Open</strong>. The app is signed and notarized by Apple.</p><p><strong>Windows says &quot;Windows protected your PC&quot;</strong> Click <strong>More info</strong> → <strong>Run anyway</strong>.</p><h2 id="the-persona-won-t-talk" tabindex="-1">The persona won&#39;t talk <a class="header-anchor" href="#the-persona-won-t-talk" aria-label="Permalink to &quot;The persona won&#39;t talk&quot;">​</a></h2><p><strong>&quot;has no model selected and cannot reply&quot;</strong> Go to <strong>Personas</strong> → that persona → the <strong>AI</strong> tab and pick a model.</p><p><strong>Getting a 401 error, or &quot;bad key&quot;</strong> Go to System Settings → <strong>Model providers</strong> → <strong>API credentials</strong>, and click <strong>Test</strong> on that entry. If it fails, re-copy and paste the key, watching for extra spaces at either end. If you&#39;re on a subscription, check whether <strong>Claude subscription</strong> still shows <strong>On and logged in</strong>.</p><p><strong>Getting a 400 error, on and off</strong> Usually the gateway or provider is temporarily rejecting requests — try again shortly. If it keeps happening, switch to a different route, or send the raw error to your persona.</p><p><strong>A reply says &quot;The connection kept dropping — tried 6 times and could not get through&quot;</strong> When the model service drops mid-reply, the app retries on its own and removes the half-shown text. You only see this note after 6 failed tries; send the message again in a moment.</p><p><strong>Changed a setting and it didn&#39;t take effect</strong> For access method, model, or search settings, reopen that persona after making the change.</p><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h2><p><strong>It doesn&#39;t remember what we just said</strong> When a conversation runs long, the persona reorganizes its context and starts a fresh thread — the raw chat text doesn&#39;t all carry over, but anything important has already been saved to memory. To make sure something sticks, say &quot;Remember: …&quot; explicitly.</p><p><strong>It remembers something wrong</strong> Just correct it directly: &quot;No, it should be…&quot;. It will overwrite the old memory.</p><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h2><p><strong>The bot isn&#39;t receiving messages</strong> Make sure the app is running; open the persona and check that the card shows <strong>Running</strong>. If you changed permissions or events in Feishu or DingTalk, you need to publish a new version; for Discord, make sure <strong>Message Content Intent</strong> is turned on. See <a href="/aibutler/docs-versions/v1.1.9/en/guide/channels.html">Channels</a> for details.</p><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><p><strong>Can&#39;t find anything</strong> See <a href="/aibutler/docs-versions/v1.1.9/en/guide/search.html">Web Search</a>. In mainland China, adding Tavily usually solves it.</p><h2 id="where-s-the-data" tabindex="-1">Where&#39;s the data <a class="header-anchor" href="#where-s-the-data" aria-label="Permalink to &quot;Where&#39;s the data&quot;">​</a></h2><p>All data lives on your own computer. On Mac it defaults to <code>~/Library/Application Support/butler</code>, on Windows to <code>%APPDATA%\\butler</code>. Each persona&#39;s files are in the folder you chose when creating it.</p><p>To see where it is now, or move it to another drive, open Settings → <strong>Advanced</strong> → <strong>Data folder</strong>. It shows the current path; <strong>Open folder</strong> opens it in Finder or Explorer. With <strong>Move elsewhere…</strong>, pick a new folder and the app restarts, copies everything over, and switches only if the copy succeeds. The old copy is left untouched — delete it yourself once you&#39;ve checked everything is fine.</p><p><img src="'+r+'" alt="Data folder under Settings → Advanced"></p><p><strong>Only one copy of the app can run on the same data folder.</strong> Opening it again while it&#39;s running just brings the open window to the front.</p>',23)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
